insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-00000000001f', 'en', null, 'Journalism & Media Literacy', 'A practical introduction to reporting the news and reading it critically — news values, clear writing, sourcing, verification, ethics, and spotting misinformation. Built from openly-licensed OER Commons material on Journalism & Media Literacy (CC BY).', null, 'work', 31, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-00000000001f', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"A ''news value'' that helps make an event newsworthy is…","options":["timeliness","word count","the reporter''s personal opinion","the headline font"],"answer":0,"explanation":"News values like timeliness, impact, and proximity help editors judge what to cover — see ''What news is''."},{"prompt":"The inverted pyramid structures a story by putting…","options":["a surprise twist ending","the most important information first","opinions before facts","quotes only at the very end"],"answer":1,"explanation":"Most-to-least important, so readers get the key facts up top — see ''The inverted pyramid''."},{"prompt":"The opening paragraph of a news story is called the…","options":["byline","masthead","lead","kicker"],"answer":2,"explanation":"The lead delivers the most important facts first — see ''Writing the lead''."},{"prompt":"When a source speaks ''on the record'', it means…","options":["nothing may be printed","their name and words can be published","only an editor may read it","it must never be quoted"],"answer":1,"explanation":"On the record = fully usable, with attribution — see ''Interviewing & sourcing''."},{"prompt":"To responsibly verify a claim, a journalist should…","options":["publish it fast before rivals do","confirm it with independent, primary sources","trust a single anonymous tip","assume a viral post is true"],"answer":1,"explanation":"Verification means independent confirmation before publishing — see ''Verification & ethics''."},{"prompt":"Fairness in reporting means…","options":["promoting the side you agree with","giving relevant parties a chance to respond","leaving out inconvenient facts","avoiding all direct quotes"],"answer":1,"explanation":"Fairness includes seeking response from those you write about — see ''Verification & ethics''."},{"prompt":"A primary source is…","options":["a person or document with direct, firsthand knowledge","an anonymous rumor online","an unrelated personal blog","a catchy headline"],"answer":0,"explanation":"Primary sources have direct knowledge of the event — see ''Interviewing & sourcing''."},{"prompt":"A warning sign that a news claim may be misinformation is…","options":["a named reporter and a correction policy","a linked source document","no author, no date, and no cited sources","a clearly labeled opinion column"],"answer":2,"explanation":"Missing author, date, and sourcing are classic red flags — see ''Media literacy''."}]}'::jsonb, null, 10),
  (2, 'What news is (and what makes it newsworthy)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define news and name the main news values editors use to choose stories. Warm-up: from the diagnostic, name one thing that can make an event newsworthy."},{"heading":"The idea","text":"News is a *timely, factual* account of something that matters to an audience. To decide what to cover, journalists weigh *news values*: timeliness (how recent), proximity (how close to the audience), impact (how many people are affected), prominence (well-known people or institutions), conflict, human interest, and novelty. A useful modern test is ''so what?'' — can you state clearly why the audience should care?"},{"heading":"Worked example","text":"Two tips arrive. (a) A city council votes to raise water rates for 40,000 residents. (b) A councilmember tried a new café at lunch. Tip (a) wins on *impact* and *proximity* — it changes real bills for many local people. Tip (b) scores near zero on every news value: it is trivia, not news."},{"heading":"Your turn","text":"Name the strongest news value for each: (1) a factory closes, laying off 300 local workers; (2) an earthquake struck this morning; (3) the country''s president is directly involved; (4) a two-headed turtle hatched at the zoo. Answers: 1-impact, 2-timeliness, 3-prominence, 4-novelty."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing what is interesting *to you* with what matters to the audience. Mistake: treating gossip or rumor as news. Exit: (a) Which news value is about how many people an event affects? (b) Which is about how recent it is? Answers: impact; timeliness."}]}'::jsonb, 'News values are tools for judgment, not a rigid checklist — most stories score high on only a few.', 12),
  (3, 'The inverted pyramid and writing the lead', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Write a tight lead and structure a story using the inverted pyramid. Warm-up: what belongs at the very top of the pyramid?"},{"heading":"The idea","text":"The *inverted pyramid* arranges facts from most to least important, so a reader who stops after one paragraph still gets the point. The *lead* — the opening line — answers the essential of who, what, when, where, why and how, plus ''so what?''. Keep it to roughly one sentence and one main idea; supporting detail, context, and quotes follow in descending order of importance."},{"heading":"Worked example","text":"Wordy lead (34 words, point buried): ''In a development that took place during the course of yesterday evening''s rather lengthy municipal meeting, it was decided, after much discussion, that the rates charged for water would be increased.'' Tight rewrite (18 words, leads with impact): ''The city council voted Tuesday to raise water rates 12% for 40,000 residents, starting in August.''"},{"heading":"Your turn","text":"Order these paragraphs by the inverted pyramid: (a) background on past rate changes, (b) the vote and its cost to residents, (c) a routine closing quote, (d) the exact new rate and start date. Then tighten this lead: ''There was a fire that happened last night and it destroyed an old building that was downtown.'' Answers: order = b, d, a, c. Tight lead = ''A fire destroyed a historic downtown building Monday night.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: ''burying the lead'' by opening with background instead of the key fact. Mistake: cramming all six Ws into one overloaded sentence. Exit: (a) Where does the most important fact go? (b) What is it called when the key fact is hidden lower down? Answers: first, in the lead; burying the lead."}]}'::jsonb, 'The lead is the first paragraph; put the single most important fact first, and never bury it under background.', 13),
  (4, 'Interviewing and sourcing', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Plan an interview and judge the strength of your sources. Warm-up: what does ''on the record'' mean?"},{"heading":"The idea","text":"A *source* is a person or document that provides information. *Primary sources* have firsthand knowledge; *secondary sources* report on others'' work. Attribution has levels: *on the record* (name and words usable), *on background* (usable without naming the person), and *off the record* (not for publication). Ask *open-ended* questions to draw out detail, and corroborate any serious claim with at least two independent sources."},{"heading":"Worked example","text":"A witness says, ''The company knew about the leak.'' Before publishing, do not simply print it. Ask *how* they know, request any documents, and find a second independent source who can confirm it. Swap the closed question ''Was it bad?'' for the open ''What did you see, and when?'' — the open version pulls out specific, checkable detail."},{"heading":"Your turn","text":"Label the attribution: (1) a named official you quote by name; (2) ''a source who requested anonymity''; (3) a person who says ''this is off the record''. Then pick the open-ended question: ''Did you like it?'' or ''What happened next?'' Answers: 1-on the record, 2-on background, 3-off the record (not publishable); open-ended = ''What happened next?''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: building a serious story on a single anonymous source. Mistake: leading the witness toward the answer you want. Exit: (a) How many independent sources should corroborate a serious claim, at minimum? (b) Which attribution level lets you print a name? Answers: two; on the record."}]}'::jsonb, 'On the record = publishable with a name attached; prefer named, on-the-record sources and corroborate before you trust.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In the inverted pyramid, the most important information goes…","options":["at the very end","first, in the lead","only in the headline","in a sidebar"],"answer":1,"explanation":"Most-to-least important order."},{"prompt":"The news value about how many people an event affects is…","options":["novelty","impact","the font size","the byline"],"answer":1,"explanation":"Impact measures how much the audience is affected."},{"prompt":"''On the record'' means…","options":["the quote cannot be used","the name and quote can be published","the source must stay anonymous","it is off the record"],"answer":1,"explanation":"Fully usable, with attribution."},{"prompt":"A strong lead usually…","options":["opens with lengthy background","leads with the most newsworthy fact in one clear sentence","lists all six Ws in one sentence","starts with a routine closing quote"],"answer":1,"explanation":"One main idea, most important fact first."},{"prompt":"To confirm a serious claim, you should…","options":["publish on a single tip","corroborate with independent sources","rely on one viral post","guess if the deadline is near"],"answer":1,"explanation":"Independent corroboration, ideally two sources."},{"prompt":"An open-ended interview question is…","options":["''Did you like it?''","''What happened next?''","''Was it bad?''","''Is that a yes?''"],"answer":1,"explanation":"Open questions invite detail rather than yes/no."}]}'::jsonb, null, 8),
  (6, 'Fact-checking, verification, and ethics', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Verify a claim and apply the core ethics of reporting. Warm-up: what should you do with a striking claim you cannot yet confirm?"},{"heading":"The idea","text":"*Verification* is the discipline of confirming facts before publishing — checking primary documents, confirming with independent sources, and questioning your own assumptions. Four widely shared ethical principles are: seek truth and report it (*accuracy*), minimize harm, act independently (no conflicts of interest), and be *accountable* (issue corrections). *Fairness* means letting those you criticize respond; *bias* is managed by reporting verifiable facts and keeping news separate from opinion."},{"heading":"Worked example","text":"A viral post claims a bridge ''collapsed today''. Verify before repeating it: trace the original post, check the date and place (a reverse-image search shows the photo is from 2018 in another country), and call the local authority to confirm. Result: the claim is unverified, so you do not publish. Being accurate matters more than being first."},{"heading":"Your turn","text":"Name the principle at work: (1) letting an accused party respond before publishing; (2) running a correction after an error; (3) refusing a gift from a company you cover; (4) checking a leaked document''s date and origin. Answers: 1-fairness, 2-accountability, 3-independence, 4-verification/accuracy."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating ''everyone is sharing it'' as proof. Mistake: sliding your own opinion into a news report. Exit: (a) What do you publish when you get a fact wrong? (b) Speed or accuracy first? Answers: a correction; accuracy."}]}'::jsonb, 'Accuracy over speed: if you cannot verify it, do not publish it — and correct openly when you get something wrong.', 13),
  (7, 'Media literacy: spotting misinformation and evaluating sources', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Evaluate a source and recognize common signs of misinformation. Warm-up: name one warning sign that a claim might be false."},{"heading":"The idea","text":"*Misinformation* is false information spread without intent to deceive; *disinformation* is deliberately false. To judge a source, read *laterally*: open new tabs to see who published it, their track record, and whether reputable outlets confirm it. Red flags include no author or date, outraged or emotional framing, no sources or links, doctored or out-of-context images, and headlines that do not match the article. Always tell news, opinion, and advertising apart."},{"heading":"Worked example","text":"A share reads ''STUDY PROVES...'' with no link. Apply the SIFT method: *Stop*; *Investigate* the source (a quick search shows it is a satire site); *Find* better coverage (no reputable outlet reports it); *Trace* the claim to the original (there is no such study). Conclusion: likely misinformation — do not share it, even if it feels true."},{"heading":"Your turn","text":"Identify the warning sign: (1) an article with no author and no date; (2) a photo captioned as today''s event, but reverse-search shows it is from 2015; (3) an all-caps headline demanding you ''SHARE NOW''; (4) a ''news'' piece that is actually a paid advertisement. Answers: 1-no attribution/date, 2-out-of-context image, 3-emotional manipulation, 4-undisclosed advertising."},{"heading":"Common mistakes & exit ticket","text":"Mistake: judging credibility by how professional a site looks. Mistake: sharing before verifying. Exit: (a) What does reading laterally mean? (b) How does disinformation differ from misinformation? Answers: leaving the page to check the source elsewhere; disinformation is deliberately false, while misinformation is spread without intent to deceive."}]}'::jsonb, 'Lateral reading: leave the page and open new tabs to check who is behind a claim before you trust or share it.', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"lead","translation":"the opening paragraph of a news story, carrying the most important facts","example":"A strong lead answers who, what, when, and ''so what?'' in one sentence."},{"term":"inverted pyramid","translation":"a story structure that presents information from most to least important","example":"The inverted pyramid lets a reader stop early and still get the point."},{"term":"attribution","translation":"telling readers where information came from — who said or supplied it","example":"Every claim needs attribution, such as ''according to the fire chief''."},{"term":"verification","translation":"confirming facts with reliable, independent sources before publishing","example":"Verification meant calling the hospital before printing the casualty number."},{"term":"primary source","translation":"a person or document with direct, firsthand knowledge of an event","example":"The eyewitness was a primary source; a blog summarizing it was not."},{"term":"misinformation","translation":"false or misleading information spread regardless of intent to deceive","example":"The out-of-date photo was misinformation, not a deliberate lie."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Verification means…","options":["confirming facts with reliable, independent sources before publishing","posting first and checking later","quoting one anonymous source","trusting whatever is trending"],"answer":0,"explanation":"Confirm before you publish."},{"prompt":"When you get a published fact wrong, ethics require you to…","options":["delete the story quietly","publish a correction","blame the source","ignore it"],"answer":1,"explanation":"Accountability means correcting openly."},{"prompt":"Reading ''laterally'' means…","options":["reading a page top to bottom twice","leaving the page to check who is behind the source","reading only the headline","skimming the comments"],"answer":1,"explanation":"Check the source using other tabs and outlets."},{"prompt":"Disinformation is…","options":["an honest mistake in a report","deliberately false information meant to deceive","a verified fact","a clearly labeled opinion"],"answer":1,"explanation":"Disinformation is intentionally false."},{"prompt":"A red flag for possible misinformation is…","options":["a named author and a correction policy","cited primary documents","no author, no date, and no cited sources","a link to the original study"],"answer":2,"explanation":"Missing attribution and sourcing are warning signs."},{"prompt":"Fairness in reporting means…","options":["giving those criticized a chance to respond","publishing only one side","hiding your sources","adding your own opinion as fact"],"answer":0,"explanation":"Seek response from those you write about."}]}'::jsonb, null, 8),
  (10, 'Applied project: report and write a short news story', 'writing', '{"sections":[{"heading":"The task","text":"Report and write a short news story (about 150-250 words) on a real, small event in your community — a local meeting, a new business, a school or neighborhood event. Use the inverted pyramid and at least two verified, independent sources. This is a full reporting exercise, not an opinion piece."},{"heading":"Milestones","text":"1) Pick a timely, relevant event and name the news value that makes it matter. 2) Interview at least two independent, named sources and gather on-the-record quotes. 3) Verify key facts — dates, names, numbers — against a primary document or a second source. 4) Write a tight lead answering who/what/when/where/why plus ''so what?'', then arrange the rest in the inverted pyramid. 5) Attribute every factual claim and keep any opinion clearly separate."},{"heading":"Self-check rubric","text":"Check yourself: your lead leads with the most newsworthy, verified fact in one clear sentence; you used at least two independent sources, properly attributed; every factual claim is verified and sourced, with no unverified rumor; the structure follows the inverted pyramid, with no opinion presented as fact; and you named one news value that makes the story worth telling. If all five hold, you have reported and written like a journalist."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-00000000001f' and l.position = v.pos
);
